  bool write_replay_dataset(const char* dir, int dataset_id, const std::vector<double>& data);
  struct Manifest { std::string contract_hash, config_hash, binary_sha256, git_commit; };
  struct BudgetUnit { int T, N, reps, calls_per_rep; };
  std::vector<BudgetUnit> plan_units(const std::vector<BudgetUnit>&, const std::vector<double>& cost_ms, double threshold_ms);
  long long total_calls(const std::vector<BudgetUnit>&);
